-- rebuild-carnet 031 + 032 + 033 + 034 + 035 + 036 + 037 + 038 + 039 + 040 + 041 + 042 + 043 + 044 (2026-09-29): remap reader reports to the new paragraph IDs.
-- paragraph_reports is the only table keyed by paragraph ID (src/auth/init.sql).
-- Reading history / bookmarks live in each reader's localStorage and cannot be remapped here.
-- One UPDATE through a mapping table, so a chain like 0005→0006→0007 cannot double-apply.
BEGIN;
CREATE TEMP TABLE renumber_031_032_033_034_035_036_037_038_039_040_041_042_043_044 (old_id TEXT PRIMARY KEY, new_id TEXT NOT NULL) ON COMMIT DROP;
UPDATE paragraph_reports r SET paragraph_id = m.new_id FROM renumber_031_032_033_034_035_036_037_038_039_040_041_042_043_044 m WHERE r.paragraph_id = m.old_id;
COMMIT;
